1	package nexusfixture
2	
3	import (
4		"encoding/json"
5		"mime"
6		"net/http"
7		"regexp"
8		"strconv"
9		"strings"
10	)
11	
12	// redacted is what replaces a credential or a secret value in a fixture.
13	const redacted = "<redacted>"
14	
15	// Authorization values a fixture may carry: the scheme and nothing else.
16	const (
17		authBasicRedacted  = "Basic " + redacted
18		authBearerRedacted = "Bearer " + redacted
19	)
20	
21	// ResponseHeaderAllowlist is the closed list of response headers a fixture
22	// keeps: everything else (Date, Set-Cookie, proxy and Nexus internals) is
23	// dropped by Redact and refused by CheckLeaks.
24	var ResponseHeaderAllowlist = []string{
25		"Server", "Docker-Distribution-Api-Version", "WWW-Authenticate", "Location", "Link",
26		"Docker-Content-Digest", "Content-Type", "Content-Length",
27	}
28	
29	// requestHeaderAllowlist is what Redact keeps of a request, besides the
30	// normalized Authorization.
31	var requestHeaderAllowlist = []string{"Accept"}
32	
33	// RawExchange is an exchange as the recorder read it from a Nexus: nothing is
34	// redacted yet, so it must never be written to a file as is.
35	type RawExchange struct {
36		Method, Target, Host string
37		RequestHeader        http.Header
38		Status               int
39		Header               http.Header
40		Body                 []byte
41	}
42	
43	var htmlTitle = regexp.MustCompile(`(?is)<title[^>]*>(.*?)</title>`)
44	
45	// Redact turns a raw exchange into one that is safe to write to a fixture: the
46	// Authorization value becomes a placeholder, request and response headers are
47	// filtered to their allowlists, an empty body is marked, a JSON body has the
48	// values of its secret keys replaced in place, and any other body (HTML
49	// included) is summarized: nothing tells where a secret sits in it. It does not
50	// modify raw.
51	func Redact(raw RawExchange) Exchange {
52		ex := Exchange{
53			Method: raw.Method, Target: raw.Target, Host: raw.Host,
54			RequestHeader: redactRequestHeader(raw.RequestHeader),
55			Status:        raw.Status,
56			Header:        http.Header{},
57		}
58		for _, name := range ResponseHeaderAllowlist {
59			if values := raw.Header.Values(name); len(values) > 0 {
60				ex.Header[http.CanonicalHeaderKey(name)] = append([]string(nil), values...)
61			}
62		}
63		media := mediaType(raw.Header.Get("Content-Type"))
64		switch {
65		case len(raw.Body) == 0:
66			ex.Stub = stubEmpty
67		case isHTML(media, raw.Body):
68			ex.Stub = htmlStub(raw.Body)
69		case isJSON(media):
70			ex.Body = []byte(redactSecretJSON(string(raw.Body)))
71		default:
72			ex.Stub = omittedStub(media, len(raw.Body))
73		}
74		return ex
75	}
76	
77	func redactRequestHeader(in http.Header) http.Header {
78		out := http.Header{}
79		if auth := in.Get("Authorization"); auth != "" {
80			scheme, _, _ := strings.Cut(strings.TrimSpace(auth), " ")
81			switch strings.ToLower(scheme) {
82			case "basic":
83				out.Set("Authorization", authBasicRedacted)
84			case "bearer":
85				out.Set("Authorization", authBearerRedacted)
86			}
87			// Any other scheme carries a secret we cannot place: the header is dropped.
88		}
89		for _, name := range requestHeaderAllowlist {
90			if values := in.Values(name); len(values) > 0 {
91				out[http.CanonicalHeaderKey(name)] = append([]string(nil), values...)
92			}
93		}
94		return out
95	}
96	
97	// mediaType is the lower-case media type of a Content-Type value, without its
98	// parameters; "" when the value is absent or does not parse.
99	func mediaType(contentType string) string {
100		media, _, err := mime.ParseMediaType(contentType)
101		if err != nil {
102			return ""
103		}
104		return media
105	}
106	
107	func isJSON(media string) bool {
108		return media == "application/json" || strings.HasSuffix(media, "+json")
109	}
110	
111	func isHTML(media string, body []byte) bool {
112		if media == "text/html" {
113			return true
114		}
115		head := strings.ToLower(strings.TrimSpace(string(body[:min(len(body), 64)])))
116		return strings.HasPrefix(head, "<!doctype html") || strings.HasPrefix(head, "<html")
117	}
118	
119	var plainMediaType = regexp.MustCompile(`^[a-z0-9.+_-]+/[a-z0-9.+_-]+$`)
120	
121	// omittedStub summarizes a body that is neither JSON nor HTML as
122	// "<body omitted: N bytes, media/type>". The media type comes from the server,
123	// so it is kept only when it is made of plain characters.
124	func omittedStub(media string, size int) string {
125		if !plainMediaType.MatchString(media) {
126			media = "unknown"
127		}
128		return stubOmittedStart + " " + strconv.Itoa(size) + " bytes, " + media + ">"
129	}
130	
131	// htmlStub summarizes an HTML body as "<HTML body omitted: N bytes, <title>T</title>>"
132	// (the title is left out when there is none). The title is flattened to one
133	// line so that the stub stays one.
134	func htmlStub(body []byte) string {
135		stub := stubHTMLStart + " " + strconv.Itoa(len(body)) + " bytes"
136		if m := htmlTitle.FindSubmatch(body); m != nil {
137			stub += ", <title>" + strings.Join(strings.Fields(string(m[1])), " ") + "</title>"
138		}
139		return stub + ">"
140	}
141	
142	// redactSecretJSON replaces the value of each secret JSON key with "<redacted>",
143	// whatever the value is: a string, a number, a literal, or a whole object or
144	// array (balanced, strings skipped). A null value is kept: it holds no secret.
145	// Only the replaced values change, every other byte stays as sent. A value that
146	// is cut short is replaced up to the end of the text.
147	func redactSecretJSON(body string) string {
148		var b strings.Builder
149		last := 0
150		for from := 0; ; {
151			_, value, ok := nextSecretKey(body, from, false)
152			if !ok {
153				break
154			}
155			end := value + keptValueLen(body[value:])
156			if end == value {
157				end = valueEnd(body, value)
158				b.WriteString(body[last:value])
159				b.WriteString(`"` + redacted + `"`)
160				last = end
161			}
162			from = end
163		}
164		b.WriteString(body[last:])
165		return b.String()
166	}
167	
168	// secretKeySuffixes end the lower-cased name of a key that holds a secret
169	// ("accessToken", "proxy_password", "apiKey"); "tokenType" does not end with one.
170	var secretKeySuffixes = []string{
171		"token", "tokens", "password", "passwords", "passwd", "passphrase", "secret", "secrets",
172		"apikey", "api_key", "api-key", "privatekey", "private_key", "private-key",
173		"credential", "credentials", "uploaderip",
174	}
175	
176	// isSecretKey reports whether a JSON key, as written between its quotes, names a
177	// secret. Escapes are decoded first, so "pass\u0077ord" is "password".
178	func isSecretKey(raw string) bool {
179		if strings.Contains(raw, `\`) {
180			var key string
181			if json.Unmarshal([]byte(`"`+raw+`"`), &key) == nil {
182				raw = key
183			} else {
184				raw = strings.ReplaceAll(raw, `\`, "")
185			}
186		}
187		lower := strings.ToLower(raw)
188		for _, suffix := range secretKeySuffixes {
189			if strings.HasSuffix(lower, suffix) {
190				return true
191			}
192		}
193		return false
194	}
195	
196	const jsonBlanks = " \t\r\n"
197	
198	func skipBlanks(text string, i int) int {
199		for i < len(text) && strings.IndexByte(jsonBlanks, text[i]) >= 0 {
200			i++
201		}
202		return i
203	}
204	
205	// stringEnd returns the index just after the string that opens at start, and
206	// whether it was closed. An unclosed string ends at the end of the text, or, with
207	// lineBound, at the first line break: a JSON string never holds one, and a scan
208	// of a whole fixture file must not let a stray quote shift every later pairing.
209	func stringEnd(text string, start int, lineBound bool) (int, bool) {
210		for i := start + 1; i < len(text); i++ {
211			switch text[i] {
212			case '\\':
213				if !lineBound || i+1 >= len(text) || text[i+1] != '\n' {
214					i++ // the escaped character
215				}
216			case '"':
217				return i + 1, true
218			case '\n':
219				if lineBound {
220					return i, false
221				}
222			}
223		}
224		return len(text), false
225	}
226	
227	// nextSecretKey finds the first member at or after from whose key names a
228	// secret. It returns where the key starts and where its value starts (after the
229	// colon and the blanks).
230	func nextSecretKey(text string, from int, lineBound bool) (key, value int, ok bool) {
231		for i := from; i < len(text); {
232			q := strings.IndexByte(text[i:], '"')
233			if q < 0 {
234				break
235			}
236			start := i + q
237			end, closed := stringEnd(text, start, lineBound)
238			i = end
239			if !closed {
240				continue
241			}
242			if colon := skipBlanks(text, end); colon < len(text) && text[colon] == ':' && isSecretKey(text[start+1:end-1]) {
243				return start, skipBlanks(text, colon+1), true
244			}
245		}
246		return 0, 0, false
247	}
248	
249	// valueEnd returns the index just after the JSON value that starts at start: a
250	// string, an object or array up to its matching bracket (strings skipped), or a
251	// bare number or literal. A value cut short ends at the end of the text.
252	func valueEnd(text string, start int) int {
253		if start >= len(text) {
254			return start
255		}
256		switch text[start] {
257		case '"':
258			end, _ := stringEnd(text, start, false)
259			return end
260		case '{', '[':
261			depth := 0
262			for i := start; i < len(text); i++ {
263				switch text[i] {
264				case '"':
265					end, _ := stringEnd(text, i, false)
266					i = end - 1
267				case '{', '[':
268					depth++
269				case '}', ']':
270					if depth--; depth == 0 {
271						return i + 1
272					}
273				}
274			}
275			return len(text)
276		}
277		i := start
278		for i < len(text) && strings.IndexByte(",}]"+jsonBlanks, text[i]) < 0 {
279			i++
280		}
281		return i
282	}
283	
284	// keptValueLen is the length of the value at the start of rest when it holds no
285	// secret, "<redacted>" or null, and 0 for any other value.
286	func keptValueLen(rest string) int {
287		const placeholder = `"` + redacted + `"`
288		switch {
289		case strings.HasPrefix(rest, placeholder):
290			return len(placeholder)
291		case strings.HasPrefix(rest, "null") && (len(rest) == 4 || strings.IndexByte(",}]"+jsonBlanks, rest[4]) >= 0):
292			return 4
293		}
294		return 0
295	}
