187	// match picks the exchange recorded for the method, target and identity: the
188	// exact target first, then the catalog tolerance.
189	func match(routes []route, method, target string, id nexusfixture.Identity) (route, bool) {
190		for _, rt := range routes {
191			if rt.identity == id && rt.ex.Method == method && rt.ex.Target == target {
192				return rt, true
193			}
194		}
195		if method != http.MethodGet {
196			return route{}, false
197		}
198		return matchCatalogTolerance(routes, target, id)
199	}
200	
201	// toleratedN is the only n (what DevDesk asks) tolerated without "last".
202	const toleratedN = 1000
203	
204	// matchCatalogTolerance lets "GET P?n=1000" (no "last") be answered by a fixture
205	// recorded as "GET P" without a query, provided that answer is a 200 with no Link
206	// and lists at most 1000 names: one page holds the whole catalog, as with n=1000.
207	// Any other n is not measured and is not tolerated.
208	//
209	// Measured: n=1000 and no n answer identically on the group connector
210	// (page-group-n1000--admin and catalog-group-connector-30482--admin), and, since
211	// DEVDESK-580, on the hosted and proxy catalogs by path and on the 404 of the root
212	// and of the group path (catalog-*-n1000--*, for the three identities); all pinned
213	// by TestTheCatalogToleranceHasMeasuredGround. Those exact fixtures win over the
214	// tolerance. For the other targets (the "/repository/<name>/v2/" paths, the group
215	// connector's pull and anonymous identities) it stays an inference: only no-n and
216	// n=2 were measured there. A 404 is never tolerated, so "?n=1000" on a target with
217	// no exact fixture stays unmatched.
218	func matchCatalogTolerance(routes []route, target string, id nexusfixture.Identity) (route, bool) {
219		path, rawQuery, _ := strings.Cut(target, "?")
220		query, err := url.ParseQuery(rawQuery)
221		if err != nil || len(query) != 1 || len(query["n"]) != 1 {
222			return route{}, false
223		}
224		n, err := strconv.Atoi(query.Get("n"))
225		if err != nil || n != toleratedN {
226			return route{}, false
227		}
228		for _, rt := range routes {
229			ex := rt.ex
230			if rt.identity != id || ex.Method != http.MethodGet || ex.Target != path ||
231				ex.Status != http.StatusOK || ex.Header.Get("Link") != "" {
232				continue
233			}
234			var catalog struct {
235				Repositories []string `json:"repositories"`
236			}
237			if json.Unmarshal(ex.Body, &catalog) == nil && catalog.Repositories != nil && len(catalog.Repositories) <= n {
238				return rt, true
239			}
240		}
241		return route{}, false
242	}
243	
244	// rewrittenHeaders carry an address of the recorded host; they are pointed at the
245	// fake server of that host. A body is data and is never rewritten.
246	var rewrittenHeaders = []string{"Link", "Location", "Www-Authenticate"}
247	
248	// replay writes the recorded status, headers and body. Content-Length is never
249	// copied: it is recomputed from the body actually served, since a stub is shorter
250	// than the answer it summarises.
251	func (s *Server) replay(w http.ResponseWriter, rt route) {
252		s.mu.Lock()
253		s.hits[rt.fixture]++
254		rewriter := s.rewriter
255		s.mu.Unlock()
256	
257		ex := rt.ex
258		h := w.Header()
259		for name, values := range ex.Header {
260			if name == "Content-Length" {
261				continue
262			}
263			rewrite := contains(rewrittenHeaders, name)
264			for _, v := range values {
265				if rewrite {
266					v = rewriter.Replace(v)
267				}
268				h.Add(name, v)
269			}
270		}
271		if len(ex.Header.Values("Content-Type")) == 0 {
272			h["Content-Type"] = nil // a nil value stops Go from sniffing one
273		}
274		body, _ := bodyOf(ex) // a stub without a stand-in was refused by New
275		h.Set("Content-Length", strconv.Itoa(len(body)))
276		w.WriteHeader(ex.Status)
277		_, _ = w.Write(body)
278	}
279	
280	var htmlTitle = regexp.MustCompile(`, (<title>.*</title>)>$`)
281	
282	// emptyStub is the stub of a recorded empty body.
283	const emptyStub = "<empty body>"
284	
285	// bodyOf is the body to serve: the recorded one, or a stand-in for a summarised
286	// body. Only two stubs have a faithful one: an empty body and an HTML page that
287	// kept its title. valid is false for any other stub.
288	func bodyOf(ex nexusfixture.Exchange) (body []byte, valid bool) {
289		switch {
290		case ex.Stub == "":
291			return ex.Body, true
292		case ex.Stub == emptyStub:
293			return nil, true
294		case strings.HasPrefix(ex.Stub, "<HTML body omitted:"):
295			if m := htmlTitle.FindStringSubmatch(ex.Stub); m != nil {
296				return []byte("<html><head>" + m[1] + "</head></html>"), true
297			}
298		}
299		return nil, false
300	}
301	
302	func contains(list []string, s string) bool {
303		for _, v := range list {
304			if v == s {
305				return true
306			}
307		}
308		return false
309	}
