15	
16	//go:embed fixtures
17	var embedded embed.FS
18	
19	const (
20		fixturesDir = "fixtures"
21	
22		// recordedByRecorder is the recorded-by value only the recorder writes.
23		recordedByRecorder = "nexus-bench record"
24	)
25	
26	// evidenceDirs maps a campaign to the dated measurement it was imported from,
27	// relative to the repository root.
28	var evidenceDirs = map[string]string{
29		"catalog": "docs/measurements/nexus-catalog",
30	}
31	
32	// Load reads the fixtures of one embedded campaign, sorted by name. It refuses
33	// a pending fixture: a request without an answer cannot be replayed.
34	func Load(campaign string) ([]Fixture, error) {
35		sub, err := fs.Sub(embedded, fixturesDir)
36		if err != nil {
37			return nil, fmt.Errorf("nexusfixture: %w", err)
38		}
39		return LoadFS(sub, campaign)
40	}
41	
42	// LoadFS is Load over any file system: it reads <campaign>/*.http from fsys.
43	func LoadFS(fsys fs.FS, campaign string) ([]Fixture, error) {
44		entries, err := fs.ReadDir(fsys, campaign)
45		if err != nil {
46			return nil, fmt.Errorf("nexusfixture: campaign %q: %w", campaign, err)
47		}
48		var fixtures []Fixture
49		for _, e := range entries {
50			if e.IsDir() || !strings.HasSuffix(e.Name(), fileSuffix) {
51				continue
52			}
53			data, err := fs.ReadFile(fsys, path.Join(campaign, e.Name()))
54			if err != nil {
55				return nil, fmt.Errorf("nexusfixture: campaign %q: %w", campaign, err)
56			}
57			f, err := Parse(campaign, e.Name(), data)
58			if err != nil {
59				return nil, err
60			}
61			if f.Meta.Record == RecordPending {
62				return nil, fmt.Errorf("nexusfixture: %s is pending (no recorded answer): run the recorder first", f.Name)
63			}
64			fixtures = append(fixtures, f)
65		}
66		sort.Slice(fixtures, func(i, j int) bool { return fixtures[i].Name < fixtures[j].Name })
67		return fixtures, nil
68	}
69	
70	// Campaigns lists the embedded campaigns, sorted.
71	func Campaigns() []string {
72		entries, err := fs.ReadDir(embedded, fixturesDir)
73		if err != nil {
74			return nil
75		}
76		var names []string
77		for _, e := range entries {
78			if e.IsDir() {
79				names = append(names, e.Name())
80			}
81		}
82		sort.Strings(names)
83		return names
84	}
85	
86	// All loads every embedded campaign.
87	func All() ([]Fixture, error) {
88		var all []Fixture
89		for _, c := range Campaigns() {
90			fixtures, err := Load(c)
91			if err != nil {
92				return nil, err
93			}
94			all = append(all, fixtures...)
95		}
96		return all, nil
97	}
98	
99	// EvidenceDir is the directory under docs/measurements/ whose files a
100	// campaign's unrecorded fixtures are byte-identical to.
101	func EvidenceDir(campaign string) (string, bool) {
102		dir, ok := evidenceDirs[campaign]
103		return dir, ok
104	}
105	
106	// CheckProvenance reports why a fixture may not pass as measured, or nil. A
107	// fixture is either recorded-by "nexus-bench record", or byte-identical to its
108	// dated evidence under repoRoot (the repository root, see EvidenceDir). Any other
109	// recorded-by value, a campaign with no evidence directory, a missing evidence
110	// file and a difference are errors that name the fixture.
111	func CheckProvenance(f Fixture, repoRoot string) error {
112		if f.Meta.RecordedBy == recordedByRecorder {
113			return nil
114		}
115		if f.Meta.RecordedBy != "" {
116			return fmt.Errorf("nexusfixture: %s: recorded-by = %q, want empty or %q", f.Name, f.Meta.RecordedBy, recordedByRecorder)
117		}
118		evidence, ok := EvidenceDir(f.Campaign)
119		if !ok {
120			return fmt.Errorf("nexusfixture: %s: campaign %q has no evidence directory and the fixture is not recorded-by %s", f.Name, f.Campaign, recordedByRecorder)
121		}
122		want, err := os.ReadFile(filepath.Join(repoRoot, filepath.FromSlash(evidence), f.Name+fileSuffix))
123		if err != nil {
124			return fmt.Errorf("nexusfixture: %s: neither recorded-by %s nor backed by its evidence: %w", f.Name, recordedByRecorder, err)
125		}
126		if got := Format(f); !bytes.Equal(got, want) {
127			return fmt.Errorf("nexusfixture: %s is not byte-identical to %s/%s%s and is not recorded-by %s", f.Name, evidence, f.Name, fileSuffix, recordedByRecorder)
128		}
129		return nil
130	}
131	
132	// SourceDir is the fixtures directory in the source tree, for the recorder
133	// (the embedded copy is read-only). It never answers with a path that is not
134	// there: under -trimpath runtime.Caller gives a module-relative path, so the
135	// answer is then an empty path and an error.
136	func SourceDir() (string, error) {
137		_, file, _, ok := runtime.Caller(0)
138		if !ok || !filepath.IsAbs(file) {
139			return "", fmt.Errorf("nexusfixture: cannot locate the source tree")
140		}
141		dir := filepath.Join(filepath.Dir(file), fixturesDir)
142		if info, err := os.Stat(dir); err != nil || !info.IsDir() {
143			return "", fmt.Errorf("nexusfixture: cannot locate the source tree: %s is not a directory", dir)
144		}
145		return dir, nil
146	}
