363	// assertPlantedLeak checks one planted fixture: every leak sits on the line of
364	// the plant, one of them carries the expected rule, and none repeats the value.
365	func assertPlantedLeak(t *testing.T, data string, tc leakCase) {
366		t.Helper()
367		at := tc.at
368		if at == "" {
369			at = tc.planted
370		}
371		line := lineOf(data, at)
372		if line == 0 {
373			t.Fatalf("the planted value %q is not in the fixture: the case is broken", at)
374		}
375		leaks := nexusfixture.CheckLeaks("planted--admin", []byte(data), tc.exact)
376		if len(leaks) == 0 {
377			t.Fatalf("no leak reported for a planted %s:\n%s", tc.name, data)
378		}
379		found := false
380		for _, l := range leaks {
381			if l.Fixture != "planted--admin" {
382				t.Errorf("Leak.Fixture = %q, want the name given to CheckLeaks", l.Fixture)
383			}
384			if l.Rule == "" {
385				t.Errorf("a leak at line %d has no Rule", l.Line)
386			}
387			if l.Line != line {
388				t.Errorf("leak %q reported at line %d, want line %d (the only line that changed)", l.Rule, l.Line, line)
389			}
390			found = found || (l.Rule == tc.rule && l.Line == line)
391		}
392		if !found {
393			t.Errorf("no leak with rule %q at line %d, got %v", tc.rule, line, leaks)
394		}
395		if echoed := fmt.Sprintf("%+v %#v", leaks, leaks); strings.Contains(echoed, tc.planted) {
396			t.Errorf("the leaks repeat the planted value: %s", echoed)
397		}
398	}
