160	// registryDo sends one request, answering a Bearer challenge once. The caller
161	// closes the response body and reads the status.
162	func registryDo(method, rawURL, accept, username, password, token string) (*http.Response, string, error) {
163		return registryDoContext(context.Background(), method, rawURL, accept, username, password, token)
164	}
165	
166	// registryDoContext is registryDo bound to ctx.
167	func registryDoContext(ctx context.Context, method, rawURL, accept, username, password, token string) (*http.Response, string, error) {
168		resp, err := doRequestContext(ctx, method, rawURL, accept, username, password, token)
169		if err != nil {
170			return nil, token, err
171		}
172		if resp.StatusCode != http.StatusUnauthorized {
173			return resp, token, nil
174		}
175		challenge := resp.Header.Get("Www-Authenticate")
176		_ = resp.Body.Close()
177		if !strings.HasPrefix(challenge, "Bearer ") {
178			return nil, token, &StatusError{Code: http.StatusUnauthorized, Source: SourceRegistry, Challenge: challenge, unexpectedChallenge: true}
179		}
180		// exchangeBearerTokenContext refuses an insecure realm itself, before any request.
181		token, err = exchangeBearerTokenContext(ctx, rawURL, challenge[7:], username, password)
182		if err != nil {
183			return nil, "", err
184		}
185		if resp, err = doRequestContext(ctx, method, rawURL, accept, "", "", token); err != nil {
186			return nil, token, fmt.Errorf("%s (retry) %s: %w", method, RedactURL(rawURL), err)
187		}
188		return resp, token, nil
189	}
190	
191	// doRequest sends one request: a bearer token when there is one, Basic auth
192	// when there are credentials and no token.
193	func doRequest(method, rawURL, accept, username, password, token string) (*http.Response, error) {
194		return doRequestContext(context.Background(), method, rawURL, accept, username, password, token)
195	}
196	
197	// doRequestContext is doRequest bound to ctx; a context already done sends
198	// nothing.
199	func doRequestContext(ctx context.Context, method, rawURL, accept, username, password, token string) (*http.Response, error) {
200		req, err := http.NewRequestWithContext(ctx, method, rawURL, nil)
201		if err != nil {
202			return nil, buildRequestError("build request", rawURL, err)
203		}
204		if accept != "" {
205			req.Header.Set("Accept", accept)
206		}
207		switch {
208		case token != "":
209			req.Header.Set("Authorization", "Bearer "+token)
210		case username != "" && password != "":
211			req.SetBasicAuth(username, password)
212		}
213		resp, err := registryHTTPClient.Do(req)
214		if err != nil {
215			return nil, fmt.Errorf("%s %s: %w", method, RedactURL(rawURL), StripRedirectTarget(err))
216		}
217		return resp, nil
218	}
219	
220	// buildRequestError is the error of a request that could not be built. The
221	// *url.Error net/http returns holds the raw URL, password included, so only the
222	// cause and the redacted URL are kept.
223	func buildRequestError(what, rawURL string, err error) error {
224		var ue *url.Error
225		if errors.As(err, &ue) {
226			err = ue.Err
227		}
228		return fmt.Errorf("%s for %s: %w", what, RedactURL(rawURL), err)
229	}
230	
231	// manifestAccept lists every manifest kind a tag can point to. A multi-platform
232	// tag is an index (or a Docker manifest list), and its digest is the one `docker
233	// pull` records in RepoDigests; asking for a single-platform manifest only
234	// would make the registry convert or refuse, and the digests would not match.
235	var manifestAccept = strings.Join([]string{
236		"application/vnd.oci.image.index.v1+json",
237		"application/vnd.docker.distribution.manifest.list.v2+json",
238		"application/vnd.oci.image.manifest.v1+json",
239		"application/vnd.docker.distribution.manifest.v2+json",
240	}, ", ")
241	
242	// ManifestDigest returns the digest a tag currently points to, from the
243	// registry's Docker-Content-Digest header.
244	//
245	// It is a HEAD request: Docker Hub does not count a HEAD against the pull rate
246	// limit, and nothing but the header is needed.
247	func ManifestDigest(apiURL, repo, tag, username, password string) (string, error) {
248		rawURL := fmt.Sprintf("%s/v2/%s/manifests/%s", strings.TrimSuffix(apiURL, "/"), repo, url.PathEscape(tag))
249		resp, _, err := registryDo(http.MethodHead, rawURL, manifestAccept, username, password, "")
250		if err != nil {
251			return "", err
252		}
253		_ = resp.Body.Close()
254		if resp.StatusCode != http.StatusOK {
255			return "", fmt.Errorf("registry returned %d for %s:%s", resp.StatusCode, repo, tag)
256		}
257		digest := resp.Header.Get("Docker-Content-Digest")
258		if digest == "" {
259			return "", fmt.Errorf("registry gave no digest for %s:%s", repo, tag)
260		}
261		return digest, nil
262	}
263	
264	// RegistryAPIBase is the v2 API root of a registry named in an image reference:
265	// Docker Hub has its own host, a local registry is reached over plain HTTP, and
266	// everything else over HTTPS. An empty registry is Docker Hub.
267	func RegistryAPIBase(registry string) string {
268		switch {
269		case registry == "":
270			return "https://registry-1.docker.io"
271		case strings.HasPrefix(registry, "localhost") || strings.HasPrefix(registry, "127.0.0.1"):
272			return "http://" + registry
273		}
274		return "https://" + registry
275	}
276	
277	// hostOf is the host of rawURL, or "" when it does not parse.
278	func hostOf(rawURL string) string {
279		u, err := url.Parse(rawURL)
280		if err != nil {
281			return ""
282		}
283		return u.Host
284	}
285	
286	// resolveNext is the URL a Link header's rel="next" points to, resolved against
287	// the page it came with — registries send it as a path — or "" when there is
288	// none. A next link that leads back to the page just read ends the walk rather
289	// than looping on it.
290	func resolveNext(current, link string) string {
291		for _, part := range strings.Split(link, ",") {
292			target, rel, ok := strings.Cut(strings.TrimSpace(part), ";")
293			if !ok || !strings.Contains(rel, `rel="next"`) {
294				continue
295			}
296			target = strings.Trim(strings.TrimSpace(target), "<>")
297			base, err := url.Parse(current)
298			if err != nil {
299				return ""
300			}
301			ref, err := url.Parse(target)
302			if err != nil {
303				return ""
304			}
305			if next := base.ResolveReference(ref).String(); next != current {
306				return next
307			}
308		}
309		return ""
310	}
311	
312	// exchangeBearerToken fetches a bearer token from the registry's token endpoint.
313	func exchangeBearerToken(registryURL, challenge, username, password string) (string, error) {
314		return exchangeBearerTokenContext(context.Background(), registryURL, challenge, username, password)
315	}
316	
317	// checkTokenRealm refuses, before any request to it, a Bearer realm that is
318	// neither http nor https (a relative realm included). It also refuses an http
319	// realm when the registry is https or cannot be parsed, whatever the
320	// credentials: the realm would otherwise receive them (or a token request) in
321	// clear. A missing or unparsable realm passes: exchangeBearerTokenContext
322	// reports those. The error names the realm's host only, never its userinfo,
323	// path or query.
324	func checkTokenRealm(registryURL, challenge string) error {
325		realm, ok := parseBearerChallenge(challenge)["realm"]
326		if !ok {
327			return nil
328		}
329		u, err := url.Parse(realm)
330		if err != nil {
331			return nil
332		}
333		reg, _ := url.Parse(registryURL)
334		switch {
335		case u.Scheme == "https":
336			return nil
337		case u.Scheme == "http" && reg != nil && reg.Scheme != "https":
338			return nil
339		case u.Hostname() == "":
340			return errInsecureTokenRealm
341		}
342		return fmt.Errorf("%w (%s)", errInsecureTokenRealm, u.Host)
343	}
344	
345	// exchangeBearerTokenContext is exchangeBearerToken bound to ctx. It applies
346	// checkTokenRealm itself, so no caller reaches an insecure realm by skipping
347	// registryDoContext; registryURL is the registry that sent the challenge.
348	func exchangeBearerTokenContext(ctx context.Context, registryURL, challenge, username, password string) (string, error) {
349		if err := checkTokenRealm(registryURL, challenge); err != nil {
350			return "", err
351		}
352		u, err := tokenEndpoint(challenge)
353		if err != nil {
354			return "", err
355		}
356		req, err := http.NewRequestWithContext(ctx, http.MethodGet, u, nil)
357		if err != nil {
358			return "", buildRequestError("build token request", u, err)
359		}
360		if username != "" && password != "" {
361			req.SetBasicAuth(username, password)
362		}
363		resp, err := registryHTTPClient.Do(req)
364		if err != nil {
365			return "", fmt.Errorf("fetch token: %w", StripRedirectTarget(err))
366		}
367		defer func() { _ = resp.Body.Close() }()
368		if resp.StatusCode != http.StatusOK {
369			return "", &StatusError{Code: resp.StatusCode, Source: SourceToken}
370		}
371		return readToken(resp.Body)
372	}
373	
374	// tokenEndpoint is the URL of the token request a Bearer challenge asks for: its
375	// realm, with the service and scope it names as the query.
376	func tokenEndpoint(challenge string) (string, error) {
377		params := parseBearerChallenge(challenge)
378		realm, ok := params["realm"]
379		if !ok {
380			return "", fmt.Errorf("bearer challenge missing realm")
381		}
382		u, err := url.Parse(realm)
383		if err != nil {
384			// The raw realm may hold a userinfo or a signed query: only the cause stays.
385			var ue *url.Error
386			if errors.As(err, &ue) {
387				err = ue.Err
388			}
389			return "", fmt.Errorf("parse realm: %w", err)

374	// tokenEndpoint is the URL of the token request a Bearer challenge asks for: its
375	// realm, with the service and scope it names as the query.
376	func tokenEndpoint(challenge string) (string, error) {
377		params := parseBearerChallenge(challenge)
378		realm, ok := params["realm"]
379		if !ok {
380			return "", fmt.Errorf("bearer challenge missing realm")
381		}
382		u, err := url.Parse(realm)
383		if err != nil {
384			// The raw realm may hold a userinfo or a signed query: only the cause stays.
385			var ue *url.Error
386			if errors.As(err, &ue) {
387				err = ue.Err
388			}
389			return "", fmt.Errorf("parse realm: %w", err)
390		}
391		q := u.Query()
392		if s, ok := params["service"]; ok {
393			q.Set("service", s)
394		}
395		if s, ok := params["scope"]; ok {
396			q.Set("scope", s)
397		}
398		u.RawQuery = q.Encode()
399		return u.String(), nil
400	}
401	
402	// readToken reads a token endpoint's answer, at most maxTokenResponse bytes, and
403	// returns the token it holds.
404	func readToken(body io.Reader) (string, error) {
405		data, err := io.ReadAll(io.LimitReader(body, maxTokenResponse+1))
406		if err != nil {
407			return "", fmt.Errorf("read token response: %w", err)
408		}
409		if len(data) > maxTokenResponse {
410			return "", fmt.Errorf("token response over %d bytes", maxTokenResponse)
411		}
412		var result struct {
413			Token       string `json:"token"`
414			AccessToken string `json:"access_token"`
415		}
416		if err := json.Unmarshal(data, &result); err != nil {
417			return "", fmt.Errorf("decode token response: %w", err)
418		}
419		if result.Token != "" {
420			return result.Token, nil
421		}
422		if result.AccessToken != "" {
423			return result.AccessToken, nil
424		}
425		return "", fmt.Errorf("token response contained no token field")
426	}
427	
428	// parseBearerChallenge parses the value portion of a Www-Authenticate: Bearer header.
429	// Example: `realm="https://auth.docker.io/token",service="registry.docker.io"`
430	func parseBearerChallenge(s string) map[string]string {
431		params := make(map[string]string)
432		for _, part := range strings.Split(s, ",") {
433			part = strings.TrimSpace(part)
434			idx := strings.IndexByte(part, '=')
435			if idx < 0 {
436				continue
437			}
438			key := strings.TrimSpace(part[:idx])
439			val := strings.Trim(strings.TrimSpace(part[idx+1:]), `"`)
440			params[key] = val
441		}
442		return params
443	}
