func TestRedactedErrorMessageIsCleanAndAddressFree(t *testing.T) {
	raw := rawJSONExchange(`{"errors":[{"code":"UNKNOWN","message":"dial tcp 10.43.12.7:5000: connect: connection refused"}]}`)
